{"command":"python3 -c "
import shutil, tempfile, glob

for archive in glob.glob('assets/*'):
    tmp = tempfile.mkdtemp()
    try:
        if archive.endswith('.gz') and not archive.endswith('.tar.gz'):
            import gzip
            out_name = archive.replace('assets/', '').replace('.gz', '')
            with gzip.open(archive, 'rb') as f_in:
                with open(tmp + '/' + out_name, 'wb') as f_out:
                    f_out.write(f_in.read())
        else:
            shutil.unpack_archive(archive, tmp)
        print(f'{archive:30}: unpacked -> {glob.glob(tmp + \"/*\")}')
    except Exception as e:
        print(f'{archive:30}: error {e}')
    finally:
        shutil.rmtree(tmp)
""}

