use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct Config {
    pub default_editor: String,
    pub match_vim_exit_behavior: bool,
    pub default_show_hidden: bool,
    pub exec: HashMap<String, Vec<String>>,
    pub config_dir: Option<PathBuf>,
}

impl Config {
    pub fn load() -> Self {
        let mut config = Config {
            default_editor: env::var("EDITOR").unwrap_or_else(|_| "vim".to_string()),
            match_vim_exit_behavior: false,
            default_show_hidden: true,
            exec: HashMap::new(),
            config_dir: None,
        };

        let config_path = get_config_file_path();
        if let Some(path) = config_path {
            if path.exists() {
                config.config_dir = path.parent().map(|p| p.to_path_buf());
                if let Ok(content) = fs::read_to_string(&path) {
                    config.parse_yaml(&content);
                }
            }
        }

        config
    }

    fn parse_yaml(&mut self, yaml: &str) {
        let mut current_section: Option<String> = None;
        let mut current_exec_ext: Option<String> = None;

        for line in yaml.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }

            let indent = line.chars().take_while(|c| c.is_whitespace()).count();

            if indent == 0 {
                current_exec_ext = None;
                if let Some((key, val)) = parse_key_value(trimmed) {
                    match key.as_str() {
                        "default_editor" => {
                            let clean_val = unquote(&val);
                            if !clean_val.is_empty() {
                                self.default_editor = clean_val;
                            }
                        }
                        "match_vim_exit_behavior" => {
                            if let Ok(b) = val.parse::<bool>() {
                                self.match_vim_exit_behavior = b;
                            }
                        }
                        "default_show_hidden" | "show_hidden" => {
                            if let Ok(b) = val.parse::<bool>() {
                                self.default_show_hidden = b;
                            }
                        }
                        "exec" => {
                            current_section = Some("exec".to_string());
                        }
                        _ => {
                            current_section = None;
                        }
                    }
                } else if trimmed.ends_with(':') {
                    let key = trimmed.trim_end_matches(':').trim();
                    if key == "exec" {
                        current_section = Some("exec".to_string());
                    } else {
                        current_section = None;
                    }
                }
            } else if current_section.as_deref() == Some("exec") {
                if trimmed.starts_with('-') {
                    // List item under an extension key
                    let item = trimmed.trim_start_matches('-').trim();
                    let clean_item = unquote(item);
                    if let Some(ref ext) = current_exec_ext {
                        self.exec
                            .entry(ext.clone())
                            .or_insert_with(Vec::new)
                            .push(clean_item);
                    }
                } else if trimmed.ends_with(':') {
                    let ext = trimmed.trim_end_matches(':').trim().trim_start_matches('.').to_string();
                    current_exec_ext = Some(ext);
                } else if let Some((key, val)) = parse_key_value(trimmed) {
                    let ext = key.trim_start_matches('.').to_string();
                    let clean_val = unquote(&val);
                    self.exec.insert(ext, vec![clean_val]);
                }
            }
        }
    }
}

pub fn get_config_file_path() -> Option<PathBuf> {
    let home = env::var("HOME").ok()?;
