                        let c = seq[0] as char;
                        Some(Key::Alt(c))
                    }
                } else {
                    Some(Key::Esc)
                }
            }
            0x20..=0x7e => Some(Key::Char(b as char)),
            _ => Some(Key::Unknown),
        }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        self.disable_raw_mode();
    }
}

fn read_nonblocking<R: Read>(reader: &mut R, buf: &mut [u8]) -> io::Result<usize> {
    // Attempt poll/select with 10ms timeout using libc or simple timeout
    use libc::{poll, pollfd, POLLIN};
    let mut fds = pollfd {
        fd: io::stdin().as_raw_fd(),
        events: POLLIN,
        revents: 0,
    };
    let ret = unsafe { poll(&mut fds, 1, 10) };
    if ret > 0 && (fds.revents & POLLIN) != 0 {
        reader.read(buf)
    } else {
        Ok(0)
    }
}
