fn init_log_file() -> Option<File> {
    let xdg_data = env::var("XDG_DATA_HOME").ok();
    let home = env::var("HOME").ok();

    let log_dir = if let Some(xdg) = xdg_data {
        PathBuf::from(xdg).join("felix").join("log")
    } else if let Some(h) = home {
        PathBuf::from(h).join(".local").join("share").join("felix").join("log")
    } else {
        PathBuf::from("/tmp/felix/log")
    };

    let _ = std_fs::create_dir_all(&log_dir);

    let now = fs::format_modified(SystemTime::now());
    // Format YYYY-MM-DD-HH-MM-SS.log
    let filename = format!("{}-{}-00.log", &now[..10], &now[11..16].replace(':', "-"));
    let log_path = log_dir.join(filename);

    OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path)
        .ok()
}

pub fn get_trash_dir() -> PathBuf {
    if let Ok(xdg) = env::var("XDG_DATA_HOME") {
        PathBuf::from(xdg).join("felix").join("Trash")
    } else if let Ok(home) = env::var("HOME") {
        PathBuf::from(home).join(".local").join("share").join("felix").join("Trash")
    } else {
        PathBuf::from("/tmp/felix/Trash")
    }
}

fn get_non_conflicting_path(dir: &Path, filename: &str) -> PathBuf {
    let mut candidate = dir.join(filename);
    if !candidate.exists() {
        return candidate;
    }

    let path = Path::new(filename);
    let stem = path.file_stem().unwrap_or_default().to_string_lossy();
    let ext = path.extension().map(|e| e.to_string_lossy());

    let mut count = 1;
    loop {
        let new_name = match &ext {
            Some(e) => format!("{}_{}.{}", stem, count, e),
            None => format!("{}_{}", stem, count),
        };
        candidate = dir.join(new_name);
        if !candidate.exists() {
            return candidate;
        }
        count += 1;
    }
}

fn copy_dir_all(src: &Path, dst: &Path) -> std::io::Result<()> {
    std_fs::create_dir_all(dst)?;
    for entry in std_fs::read_dir(src)? {
        let entry = entry?;
        let ty = entry.file_type()?;
        if ty.is_dir() {
            copy_dir_all(&entry.path(), &dst.join(entry.file_name()))?;
        } else {
            std_fs::copy(entry.path(), dst.join(entry.file_name()))?;
        }
    }
    Ok(())
}
