use crate::app::{App, AppMode};
use crate::cli::HELP_TEXT;
use crate::fs::{self, FileType};
use std::fs;
use std::io::{self, Write};
use std::process::Command;

pub fn render(app: &App, width: u16, height: u16) -> io::Result<()> {
    let mut out = io::stdout();

    // Hide cursor by default
    write!(out, "\x1b[?25l")?;

    let w = width as usize;
    let h = height as usize;

    if w < 4 || h < 3 {
        write!(out, "\x1b[1;1H\x1b[2JError: Too small window size")?;
        out.flush()?;
        return Ok(());
    }

    match app.mode {
        AppMode::HelpView => {
            render_help_view(&mut out, w, h, app.preview_scroll)?;
        }
        AppMode::RegisterView => {
            render_main_layout(&mut out, app, w, h)?;
        }
        _ => {
            render_main_layout(&mut out, app, w, h)?;
        }
    }

    out.flush()?;
    Ok(())
}

fn render_main_layout<W: Write>(out: &mut W, app: &App, w: usize, h: usize) -> io::Result<()> {
    write!(out, "\x1b[1;1H\x1b[2J")?;

    let (list_w, prev_w) = if app.preview_enabled && app.preview_split_vertical {
        let lw = (w - 1) / 2;
        (lw, w - lw - 1)
    } else {
        (w, 0)
    };

    // Row 1: Header
    let current_dir_str = app.current_dir.to_string_lossy();
    write!(out, "\x1b[1;1H\x1b[38;5;6m {}\x1b[0m", current_dir_str)?;

    if let Some(branch) = fs::get_git_branch(&app.current_dir) {
        write!(out, " on \x1b[38;5;13m\x1b[1m{}\x1b[0m", branch)?;
    }

    if app.preview_enabled && app.preview_split_vertical && prev_w > 0 {
        if let Some(item) = app.get_selected_item() {
            let header_right = format!("[{}]", item.name);
            let start_col = w.saturating_sub(header_right.len());
            write!(out, "\x1b[1;{}H{}", start_col, header_right)?;
        }
    }

    // Row 2: Status / Notification / Input prompt
    render_message_or_input(out, app, w)?;

    // Items list (Rows 3 to H-1)
    let list_height = if app.preview_enabled && !app.preview_split_vertical {
        (h - 3) / 2
    } else {
        h - 3
    };

    render_file_list(out, app, list_w, list_height)?;

    // Render Preview Pane if enabled
    if app.preview_enabled {
        if app.preview_split_vertical && prev_w > 0 {
            render_preview_vertical(out, app, list_w + 1, prev_w, list_height)?;
        } else if !app.preview_split_vertical {
            let prev_y = 3 + list_height;
            let prev_h = h - 1 - prev_y;
            render_preview_horizontal(out, app, prev_y, w, prev_h)?;
        }
    } else if app.mode == AppMode::RegisterView {
        render_register_pane(out, app, list_w + 1, prev_w, list_height)?;
    }

    // Row H: Bottom status bar
    render_bottom_status_bar(out, app, w, h)?;

    Ok(())
}

fn render_message_or_input<W: Write>(out: &mut W, app: &App, w: usize) -> io::Result<()> {
    write!(out, "\x1b[2;1H\x1b[2K")?;

    match app.mode {
        AppMode::Search => {
            write!(out, " /{}", app.input_buffer)?;
            write!(out, "\x1b[?25h")?; // Show cursor
        }
        AppMode::Command => {
            write!(out, " :{}", app.input_buffer)?;
            write!(out, "\x1b[?25h")?;
        }
        AppMode::NewFile => {
            write!(out, " New file: {}", app.input_buffer)?;
            write!(out, "\x1b[?25h")?;
        }
        AppMode::NewDir => {
            write!(out, " New directory: {}", app.input_buffer)?;
            write!(out, "\x1b[?25h")?;
        }
        AppMode::Rename => {
            write!(out, " New name: {}", app.input_buffer)?;
            write!(out, "\x1b[?25h")?;
        }
        AppMode::ConfirmTrash => {
