            write!(out, "\x1b[?25h")?;
        }
        AppMode::Rename => {
            write!(out, " New name: {}", app.input_buffer)?;
            write!(out, "\x1b[?25h")?;
        }
        AppMode::ConfirmTrash => {
            write!(out, " Are you sure to empty the trash directory? (if yes: y)")?;
        }
        _ => {
            if let Some(ref msg) = app.message {
                write!(out, " {}", msg)?;
            }
        }
    }

    Ok(())
}

fn render_file_list<W: Write>(out: &mut W, app: &App, list_w: usize, list_h: usize) -> io::Result<()> {
    let start_idx = app.scroll_offset;
    let end_idx = (start_idx + list_h).min(app.items.len());

    let date_col = list_w.saturating_sub(17);

    for (row_offset, idx) in (start_idx..end_idx).enumerate() {
        let row = 3 + row_offset;
        let item = &app.items[idx];

        let is_selected = idx == app.cursor_idx;
        let is_visual_selected = app.mode == AppMode::Visual && app.visual_selected.contains(&idx);

        let prefix = if is_selected { ">" } else { " " };

        // Color logic
        let color_code = if item.git_status_red {
            "38;5;1" // Red
        } else {
            match &item.file_type {
                FileType::Directory | FileType::SymlinkToDir(_) => "38;5;14", // Cyan
                FileType::SymlinkToFile(_) | FileType::BrokenSymlink(_) => "38;5;11", // Yellow
                FileType::File => "38;5;15", // White
            }
        };

        write!(out, "\x1b[{};1H{}", row, prefix)?;

        if is_visual_selected {
            write!(out, "\x1b[7m")?; // Invert color for visual selection
        }

        let max_name_len = date_col.saturating_sub(3);
        let display_name = truncate_str(&item.name, max_name_len);

        write!(out, "\x1b[{};3H\x1b[{}m{}\x1b[0m", row, color_code, display_name)?;

        // Date string right-aligned
        let date_str = fs::format_modified(item.modified);
        write!(out, "\x1b[{};{}H\x1b[38;5;15m {}\x1b[0m", row, date_col + 1, date_str)?;
    }

    Ok(())
}

fn render_bottom_status_bar<W: Write>(out: &mut W, app: &App, w: usize, h: usize) -> io::Result<()> {
    write!(out, "\x1b[{};1H\x1b[2K\x1b[7m", h)?; // Inverted colors

    // Fill entire line with space background
    write!(out, "{}", " ".repeat(w))?;
    write!(out, "\x1b[{};1H\x1b[7m", h)?;

    if let Some(item) = app.get_selected_item() {
        match &item.file_type {
            FileType::SymlinkToDir(target) | FileType::SymlinkToFile(target) => {
                write!(out, " linked to: {}", target.to_string_lossy())?;
            }
            FileType::BrokenSymlink(_) => {
                write!(out, " linked to: (invalid path)")?;
            }
            _ => {
                let idx_str = format!("{}/{}", app.cursor_idx + 1, app.items.len());
                let ext_str = item.extension.as_deref().unwrap_or("");
                let size_str = fs::format_size(item.size);
                let perm_str = fs::format_permissions(item.permissions);

                if ext_str.is_empty() {
                    write!(out, " {} {} {}", idx_str, size_str, perm_str)?;
                } else {
                    write!(out, " {} {} {} {}", idx_str, ext_str, size_str, perm_str)?;
                }
            }
        }
    } else {
        write!(out, " 0/0 0B 000")?;
    }

    write!(out, "\x1b[0m")?;
    Ok(())
}

fn render_preview_vertical<W: Write>(out: &mut W, app: &App, start_x: usize, prev_w: usize, prev_h: usize) -> io::Result<()> {
    if let Some(item) = app.get_selected_item() {
        match &item.file_type {
            FileType::Directory | FileType::SymlinkToDir(_) => {
                render_dir_preview(out, &item.path, start_x, 3, prev_w, prev_h, app.show_hidden)?;
            }
            FileType::File | FileType::SymlinkToFile(_) => {
                render_file_preview(out, &item.path, start_x, 3, prev_w, prev_h, app.preview_scroll)?;
            }
            _ => {}
        }
    }
    Ok(())
}

fn render_preview_horizontal<W: Write>(out: &mut W, app: &App, start_y: usize, prev_w: usize, prev_h: usize) -> io::Result<()> {
    if let Some(item) = app.get_selected_item() {
        match &item.file_type {
            FileType::Directory | FileType::SymlinkToDir(_) => {
                render_dir_preview(out, &item.path, 1, start_y, prev_w, prev_h, app.show_hidden)?;
            }
            FileType::File | FileType::SymlinkToFile(_) => {
                render_file_preview(out, &item.path, 1, start_y, prev_w, prev_h, app.preview_scroll)?;
            }
            _ => {}
        }
    }
    Ok(())
}

fn render_file_preview<W: Write>(out: &mut W, path: &std::path::Path, x: usize, y: usize, w: usize, h: usize, scroll: usize) -> io::Result<()> {
    if let Ok(content) = fs::read_to_string(path) {
        let lines: Vec<&str> = content.lines().collect();
        for (i, line) in lines.iter().skip(scroll).take(h).enumerate() {
            let truncated = truncate_str(line, w);
            write!(out, "\x1b[{};{}H{}", y + i, x, truncated)?;
        }
    }
    Ok(())
}

fn render_dir_preview<W: Write>(out: &mut W, path: &std::path::Path, x: usize, y: usize, w: usize, h: usize, show_hidden: bool) -> io::Result<()> {
    let sub_items = fs::list_directory(path, show_hidden, false);
    let total = sub_items.len();

    for (i, item) in sub_items.iter().take(h).enumerate() {
        let prefix = if i == total - 1 { "└ " } else { "├ " };
        let line = format!("{}{}", prefix, item.name);
        let truncated = truncate_str(&line, w);
        write!(out, "\x1b[{};{}H{}", y + i, x, truncated)?;
    }

    Ok(())
}

fn render_register_pane<W: Write>(out: &mut W, app: &App, x: usize, w: usize, h: usize) -> io::Result<()> {
    let mut row = 3;
    if let Some(paths) = app.registers.get &'0' {
        if let Some(first) = paths.first() {
            let name = first.file_name().unwrap_or_default().to_string_lossy();
            let line = format!("\"\" {}", name);
            write!(out, "\x1b[{};{}H{}", row, x, truncate_str(&line, w))?;
            row += 1;
        }
    }

    let mut keys: Vec<&char> = app.registers.keys().filter(|&&k| k != '0').collect();
    keys.sort();

    for k in keys {
        if row >= 3 + h {
            break;
        }
        if let Some(paths) = app.registers.get(k) {
            if let Some(first) = paths.first() {
                let name = first.file_name().unwrap_or_default().to_string_lossy();
                let line = format!("\"{} {}", k, name);
                write!(out, "\x1b[{};{}H{}", row, x, truncate_str(&line, w))?;
                row += 1;
            }
        }
    }

    Ok(())
}

fn render_help_view<W: Write>(out: &mut W, w: usize, h: usize, scroll: usize) -> io::Result<()> {
    write!(out, "\x1b[1;1H\x1b[2J")?;
    let lines: Vec<&str> = HELP_TEXT.lines().collect();

    for (i, line) in lines.iter().skip(scroll).take(h).enumerate() {
        let truncated = truncate_str(line, w);
        write!(out, "\x1b[{};1H{}", i + 1, truncated)?;
    }

    Ok(())
}

fn truncate_str(s: &str, max_len: usize) -> String {
    if max_len == 0 {
        return String::new();
    }
    if s.chars().count() > max_len {
        s.chars().take(max_len).collect()
    } else {
        s.to_string()
    }
}
