use app::{App, AppMode, UndoAction};
use cli::parse_args;
use config::get_config_file_path;
use fs::FileType;
use std::env;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;
use terminal::{Key, Terminal};

fn main() {
    let args = parse_args();

    let mut terminal = Terminal::new();
    let term_size = Terminal::get_size();

    if term_size.is_none() {
        eprintln!("Error: Cannot detect terminal size");
        std::process::exit(0);
    }

    let (mut cols, mut rows) = term_size.unwrap();

    let mut app = App::new(args);

    if cols < 4 || rows < 3 {
