    loop {
        if app.exit_requested {
            break;
        }

        if let Some((new_cols, new_rows)) = Terminal::get_size() {
            cols = new_cols;
            rows = new_rows;
        }

        if let Err(_) = ui::render(&app, cols, rows) {
            break;
        }

        if let Some(key) = terminal.read_key() {
            handle_key(&mut app, key, &mut terminal, cols, rows);
        }
    }

    terminal.disable_raw_mode();
}

fn handle_key(app: &mut App, key: Key, terminal: &mut Terminal, cols: u16, rows: u16) {
    match app.mode {
        AppMode::Normal => handle_normal_key(app, key, terminal, cols, rows),
        AppMode::Search => handle_search_key(app, key),
        AppMode::Command => handle_command_key(app, key, terminal),
        AppMode::NewFile => handle_new_file_key(app, key),
        AppMode::NewDir => handle_new_dir_key(app, key),
        AppMode::Rename => handle_rename_key(app, key),
        AppMode::Visual => handle_visual_key(app, key),
        AppMode::ConfirmTrash => handle_confirm_trash_key(app, key),
        AppMode::RegisterView => handle_register_view_key(app, key),
        AppMode::HelpView => handle_help_view_key(app, key),
    }
}

fn handle_normal_key(app: &mut App, key: Key, terminal: &mut Terminal, _cols: u16, rows: u16) {
    let list_h = (rows as usize).saturating_sub(3);

    // Clear one-time message when user types next key
    if key != Key::Unknown {
        // preserve message if setting new one
    }

    match key {
        Key::Char('q') => {
            app.exit_app(false);
        }
        Key::Char('j') | Key::Down => {
            if !app.items.is_empty() {
                if app.cursor_idx + 1 < app.items.len() {
                    app.cursor_idx += 1;
                    if app.cursor_idx >= app.scroll_offset + list_h {
                        app.scroll_offset = app.cursor_idx + 1 - list_h;
                    }
                }
            }
        }
        Key::Char('k') | Key::Up => {
            if app.cursor_idx > 0 {
                app.cursor_idx -= 1;
                if app.cursor_idx < app.scroll_offset {
                    app.scroll_offset = app.cursor_idx;
                }
            }
        }
        Key::Ctrl('d') => {
            let step = (list_h / 2).max(1);
            if !app.items.is_empty() {
                app.cursor_idx = (app.cursor_idx + step).min(app.items.len() - 1);
                if app.cursor_idx >= app.scroll_offset + list_h {
                    app.scroll_offset = app.cursor_idx + 1 - list_h;
                }
            }
        }
        Key::Ctrl('u') => {
            let step = (list_h / 2).max(1);
            app.cursor_idx = app.cursor_idx.saturating_sub(step);
            if app.cursor_idx < app.scroll_offset {
                app.scroll_offset = app.cursor_idx;
            }
        }
        Key::Char('h') | Key::Left => {
            if let Some(parent) = app.current_dir.parent().map(|p| p.to_path_buf()) {
                app.set_current_dir(parent);
            }
        }
        Key::Char('l') | Key::Right | Key::Enter => {
            if let Some(item) = app.get_selected_item().cloned() {
                match item.file_type {
                    FileType::Directory | FileType::SymlinkToDir(_) => {
                        app.set_current_dir(item.path);
                    }
                    FileType::File | FileType::SymlinkToFile(_) => {
                        // Open file in editor / app
                        let editor = app.config.default_editor.clone();
                        terminal.disable_raw_mode();
                        let _ = Command::new(editor).arg(&item.path).status();
                        terminal.enable_raw_mode();
                    }
                    _ => {}
                }
            }
        }
        Key::Char('g') => {
            // Check double g keypress handling or single g
            app.cursor_idx = 0;
            app.scroll_offset = 0;
        }
        Key::Char('G') => {
            if !app.items.is_empty() {
                app.cursor_idx = app.items.len() - 1;
                if app.items.len() > list_h {
                    app.scroll_offset = app.items.len() - list_h;
                }
            }
        }
        Key::Ctrl('o') => {
            if app.history_idx > 0 {
                app.history_idx -= 1;
                app.current_dir = app.history[app.history_idx].clone();
                app.cursor_idx = 0;
                app.scroll_offset = 0;
                app.refresh_items();
            }
        }
        Key::Ctrl('i') => {
            if app.history_idx + 1 < app.history.len() {
                app.history_idx += 1;
                app.current_dir = app.history[app.history_idx].clone();
                app.cursor_idx = 0;
                app.scroll_offset = 0;
                app.refresh_items();
            }
        }
        Key::Char('i') => {
            app.mode = AppMode::NewFile;
            app.input_buffer.clear();
        }
        Key::Char('I') => {
            app.mode = AppMode::NewDir;
            app.input_buffer.clear();
        }
        Key::Char('c') => {
            if let Some(item) = app.get_selected_item() {
                app.mode = AppMode::Rename;
                app.input_buffer = item.name.clone();
            }
        }
        Key::Char('d') => {
            // Expecting second 'd' or 'dd'
            app.delete_item('0', false);
        }
        Key::Char('y') => {
            // Expecting second 'y' or 'yy'
            app.yank_item('0', false);
        }
        Key::Char('p') => {
            app.put_item('0');
        }
        Key::Char('"') => {
            // Register prefix handling in normal mode
        }
        Key::Char('V') => {
            app.mode = AppMode::Visual;
            app.visual_anchor = Some(app.cursor_idx);
            app.visual_selected = vec![app.cursor_idx];
        }
        Key::Char('u') => {
            app.undo();
        }
        Key::Ctrl('r') => {
            app.redo();
        }
        Key::Char('v') => {
            app.preview_enabled = !app.preview_enabled;
        }
        Key::Char('s') => {
            app.preview_split_vertical = !app.preview_split_vertical;
        }
        Key::AltUp | Key::Alt('k') => {
            app.preview_scroll = app.preview_scroll.saturating_sub(1);
        }
        Key::AltDown | Key::Alt('j') => {
            app.preview_scroll += 1;
        }
        Key::Backspace => {
            app.show_hidden = !app.show_hidden;
            app.refresh_items();
        }
        Key::Char('t') => {
            app.sort_by_time = !app.sort_by_time;
            app.refresh_items();
        }
        Key::Char('/') => {
            app.mode = AppMode::Search;
            app.input_buffer.clear();
        }
        Key::Char('n') => {
            if !app.search_matches.is_empty() {
                app.search_match_pointer = (app.search_match_pointer + 1) % app.search_matches.len();
                app.cursor_idx = app.search_matches[app.search_match_pointer];
            }
        }
        Key::Char('N') => {
            if !app.search_matches.is_empty() {
                if app.search_match_pointer == 0 {
                    app.search_match_pointer = app.search_matches.len() - 1;
                } else {
                    app.search_match_pointer -= 1;
                }
                app.cursor_idx = app.search_matches[app.search_match_pointer];
            }
        }
        Key::Char(':') => {
            app.mode = AppMode::Command;
            app.input_buffer.clear();
        }
        Key::Char('e') => {
            if let Some(item) = app.get_selected_item().cloned() {
                let start_time = std::time::Instant::now();
                if fs::unpack_archive(&item.path, &app.current_dir).is_ok() {
                    let elapsed = start_time.elapsed().as_secs_f64();
                    app.message = Some(format!("Unpacked. [{:.2}s]", elapsed));
                    app.refresh_items();
                } else {
                    app.message = Some("Failed to unpack archive.".to_string());
                }
            }
        }
        Key::Char('Z') => {
            // ZZ / ZQ handling
            if app.config.match_vim_exit_behavior {
                app.exit_app(false);
            } else {
                app.exit_app(true);
            }
        }
        _ => {}
    }
}

fn handle_search_key(app: &mut App, key: Key) {
    match key {
        Key::Esc => {
            app.mode = AppMode::Normal;
            app.message = None;
        }
        Key::Enter => {
            app.mode = AppMode::Normal;
            if !app.search_matches.is_empty() {
                app.message = Some(format!(" /{} - {} matches", app.input_buffer, app.search_matches.len()));
            } else {
                app.message = Some(format!(" /{} - 0 matches", app.input_buffer));
            }
        }
        Key::Backspace => {
            app.input_buffer.pop();
            update_search(app);
        }
        Key::Char(c) => {
            app.input_buffer.push(c);
            update_search(app);
        }
        _ => {}
    }
}

fn update_search(app: &mut App) {
    let query = app.input_buffer.to_lowercase();
    app.search_matches.clear();
    app.search_match_pointer = 0;

    if query.is_empty() {
        return;
    }

    for (idx, item) in app.items.iter().enumerate() {
        if item.name.to_lowercase().contains(&query) {
            app.search_matches.push(idx);
        }
    }

    if let Some(&first) = app.search_matches.first() {
        app.cursor_idx = first;
    }
}

fn handle_command_key(app: &mut App, key: Key, terminal: &mut Terminal) {
    match key {
        Key::Esc => {
            app.mode = AppMode::Normal;
            app.input_buffer.clear();
        }
        Key::Enter => {
            let cmd_str = app.input_buffer.trim().to_string();
            app.mode = AppMode::Normal;
            app.input_buffer.clear();

            if cmd_str == "q" {
                app.exit_app(false);
            } else if cmd_str == "h" {
                app.mode = AppMode::HelpView;
                app.preview_scroll = 0;
            } else if cmd_str == "reg" {
                app.mode = AppMode::RegisterView;
            } else if cmd_str == "config" {
                if let Some(cfg_path) = get_config_file_path() {
                    if let Some(parent) = cfg_path.parent() {
                        app.set_current_dir(parent.to_path_buf());
                    } else {
                        app.message = Some("Cannot find the config path.".to_string());
                    }
                } else {
                    app.message = Some("Cannot find the config path.".to_string());
                }
            } else if cmd_str == "trash" {
                let trash = app::get_trash_dir();
                app.set_current_dir(trash);
            } else if cmd_str == "empty" {
                app.mode = AppMode::ConfirmTrash;
            } else if cmd_str == "e" {
                app.refresh_items();
            } else if cmd_str == "cd" {
                if let Ok(home) = env::var("HOME") {
                    app.set_current_dir(PathBuf::from(home));
                }
            } else if cmd_str.starts_with("cd ") {
                let path_str = cmd_str[3..].trim();
                let p = PathBuf::from(path_str);
                app.set_current_dir(p);
            } else if !cmd_str.is_empty() {
                terminal.disable_raw_mode();
                let _ = Command::new("sh")
                    .arg("-c")
                    .arg(&cmd_str)
                    .current_dir(&app.current_dir)
                    .status();
                terminal.enable_raw_mode();
                app.refresh_items();
            }
        }
        Key::Backspace => {
            app.input_buffer.pop();
        }
        Key::Char(c) => {
            app.input_buffer.push(c);
        }
        _ => {}
    }
}

fn handle_new_file_key(app: &mut App, key: Key) {
    match key {
        Key::Esc => {
            app.mode = AppMode::Normal;
            app.input_buffer.clear();
        }
        Key::Enter => {
            let filename = app.input_buffer.trim().to_string();
            app.mode = AppMode::Normal;
            app.input_buffer.clear();

            if !filename.is_empty() {
                let new_path = app.current_dir.join(&filename);
                if !new_path.exists() {
                    if let Ok(_) = std::fs::File::create(&new_path) {
                        app.refresh_items();
                        if let Some(pos) = app.items.iter().position(|i| i.name == filename) {
                            app.cursor_idx = pos;
                        }
                    }
                }
            }
        }
        Key::Backspace => {
            app.input_buffer.pop();
        }
        Key::Char(c) => {
            app.input_buffer.push(c);
        }
        _ => {}
    }
}

fn handle_new_dir_key(app: &mut App, key: Key) {
    match key {
        Key::Esc => {
            app.mode = AppMode::Normal;
            app.input_buffer.clear();
        }
        Key::Enter => {
            let dirname = app.input_buffer.trim().to_string();
            app.mode = AppMode::Normal;
            app.input_buffer.clear();

            if !dirname.is_empty() {
                let new_path = app.current_dir.join(&dirname);
                if !new_path.exists() {
                    if let Ok(_) = std::fs::create_dir_all(&new_path) {
                        app.refresh_items();
                        if let Some(pos) = app.items.iter().position(|i| i.name == dirname) {
                            app.cursor_idx = pos;
                        }
                    }
                }
            }
        }
        Key::Backspace => {
            app.input_buffer.pop();
        }
        Key::Char(c) => {
            app.input_buffer.push(c);
        }
        _ => {}
    }
}

fn handle_rename_key(app: &mut App, key: Key) {
    match key {
        Key::Esc => {
            app.mode = AppMode::Normal;
            app.input_buffer.clear();
        }
        Key::Enter => {
            let new_name = app.input_buffer.trim().to_string();
            app.mode = AppMode::Normal;
            app.input_buffer.clear();

            if let Some(item) = app.get_selected_item().cloned() {
                if !new_name.is_empty() && new_name != item.name {
                    let new_path = app.current_dir.join(&new_name);
                    if std::fs::rename(&item.path, &new_path).is_ok() {
                        app.undo_stack.push(UndoAction::Rename {
                            old_path: item.path,
                            new_path,
                        });
                        app.refresh_items();
                        if let Some(pos) = app.items.iter().position(|i| i.name == new_name) {
                            app.cursor_idx = pos;
                        }
                    }
                }
            }
        }
        Key::Backspace => {
            app.input_buffer.pop();
        }
        Key::Char(c) => {
            app.input_buffer.push(c);
        }
        _ => {}
    }
}

fn handle_visual_key(app: &mut App, key: Key) {
    match key {
        Key::Esc => {
            app.mode = AppMode::Normal;
            app.visual_anchor = None;
            app.visual_selected.clear();
        }
        Key::Char('j') | Key::Down => {
            if app.cursor_idx + 1 < app.items.len() {
                app.cursor_idx += 1;
                update_visual_selected(app);
            }
        }
        Key::Char('k') | Key::Up => {
            if app.cursor_idx > 0 {
                app.cursor_idx -= 1;
                update_visual_selected(app);
            }
        }
        Key::Char('y') => {
            app.yank_item('0', false);
        }
        Key::Char('d') => {
            app.delete_item('0', false);
        }
        _ => {}
    }
}

fn update_visual_selected(app: &mut App) {
    if let Some(anchor) = app.visual_anchor {
        let start = anchor.min(app.cursor_idx);
        let end = anchor.max(app.cursor_idx);
        app.visual_selected = (start..=end).collect();
    }
}

fn handle_confirm_trash_key(app: &mut App, key: Key) {
    match key {
        Key::Char('y') => {
            let trash = app::get_trash_dir();
            if trash.exists() {
                if let Ok(entries) = std::fs::read_dir(&trash) {
                    for entry in entries.flatten() {
                        let p = entry.path();
                        if p.is_dir() {
                            let _ = std::fs::remove_dir_all(p);
                        } else {
                            let _ = std::fs::remove_file(p);
                        }
                    }
                }
            }
            app.mode = AppMode::Normal;
            app.message = None;
            app.refresh_items();
        }
        _ => {
            app.mode = AppMode::Normal;
            app.message = None;
        }
    }
}

fn handle_register_view_key(app: &mut App, key: Key) {
    match key {
        Key::Char('v') | Key::Esc => {
            app.mode = AppMode::Normal;
        }
        _ => {}
    }
}

fn handle_help_view_key(app: &mut App, key: Key) {
    match key {
        Key::Esc | Key::Char('q') => {
            app.mode = AppMode::Normal;
        }
        Key::Char('j') | Key::Down => {
            app.preview_scroll += 1;
        }
        Key::Char('k') | Key::Up => {
            app.preview_scroll = app.preview_scroll.saturating_sub(1);
        }
        _ => {}
    }
}
