use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::SystemTime;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FileType {
    Directory,
    SymlinkToDir(PathBuf),
    SymlinkToFile(PathBuf),
    BrokenSymlink(PathBuf),
    File,
}

#[derive(Debug, Clone)]
pub struct FileItem {
    pub name: String,
    pub path: PathBuf,
    pub file_type: FileType,
    pub size: u64,
    pub permissions: u32,
    pub modified: SystemTime,
    pub extension: Option<String>,
    pub git_status_red: bool,
}

pub fn list_directory(
    dir_path: &Path,
    show_hidden: bool,
    sort_by_time: bool,
) -> Vec<FileItem> {
    let mut items = Vec::new();

    let entries = match fs::read_dir(dir_path) {
        Ok(e) => e,
        Err(_) => return items,
    };

    let git_red_files = get_git_red_files(dir_path);

    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if !show_hidden && name.starts_with('.') {
            continue;
        }

        let path = entry.path();
        let symlink_meta = fs::symlink_metadata(&path).ok();
        let meta = fs::metadata(&path).ok();

        let permissions = symlink_meta
            .as_ref()
            .map(|m| m.permissions().mode())
            .unwrap_or(0o644);

        let size = meta.as_ref().map(|m| m.len()).unwrap_or(0);

        let modified = meta
            .as_ref()
            .and_then(|m| m.modified().ok())
            .unwrap_or(SystemTime::UNIX_EPOCH);

        let is_symlink = symlink_meta.as_ref().map(|m| m.file_type().is_symlink()).unwrap_or(false);

        let file_type = if is_symlink {
            if let Ok(canonical) = path.canonicalize() {
                if canonical.is_dir() {
                    FileType::SymlinkToDir(canonical)
                } else {
                    FileType::SymlinkToFile(canonical)
                }
            } else {
                let target = fs::read_link(&path).unwrap_or_else(|_| PathBuf::from("(invalid path)"));
                FileType::BrokenSymlink(target)
            }
        } else if path.is_dir() {
            FileType::Directory
        } else {
            FileType::File
        };

        let extension = if matches!(file_type, FileType::Directory | FileType::SymlinkToDir(_)) {
            None
        } else {
            path.extension().map(|e| e.to_string_lossy().to_string())
        };

        let git_status_red = git_red_files.contains(&name);

        items.push(FileItem {
            name,
            path,
            file_type,
            size,
            permissions,
            modified,
            extension,
            git_status_red,
        });
    }

    sort_items(&mut items, sort_by_time);

    items
}

fn sort_items(items: &mut [FileItem], sort_by_time: bool) {
    if sort_by_time {
        items.sort_by(|a, b| {
            let a_is_dir = is_dir_type(&a.file_type);
            let b_is_dir = is_dir_type(&b.file_type);
            if a_is_dir != b_is_dir {
                return b_is_dir.cmp(&a_is_dir);
            }
            b.modified.cmp(&a.modified)
        });
    } else {
        items.sort_by(|a, b| {
            let a_is_dir = is_dir_type(&a.file_type);
            let b_is_dir = is_dir_type(&b.file_type);
            if a_is_dir != b_is_dir {
                return b_is_dir.cmp(&a_is_dir);
            }
            a.name.to_lowercase().cmp(&b.name.to_lowercase())
        });
    }
}

pub fn is_dir_type(ft: &FileType) -> bool {
    matches!(ft, FileType::Directory | FileType::SymlinkToDir(_))
}

fn get_git_red_files(dir_path: &Path) -> std::collections::HashSet<String> {
    let mut set = std::collections::HashSet::new();

    let output = Command::new("git")
        .arg("-C")
        .arg(dir_path)
        .arg("status")
        .arg("--porcelain")
        .output();

    if let Ok(out) = output {
        let text = String::from_utf8_lossy(&out.stdout);
        for line in text.lines() {
            if line.len() > 3 {
                let status = &line[..2];
                let file_path_str = line[3..].trim().trim_matches('"');
                if status.contains('M') || status.contains('?') || status.contains('A') || status.contains('D') {
                    if let Some(first_component) = Path::new(file_path_str).components().next() {
                        set.insert(first_component.as_os_str().to_string_lossy().to_string());
                    }
                }
            }
        }
    }

    set
}

pub fn get_git_branch(dir_path: &Path) -> Option<String> {
    let output = Command::new("git")
        .arg("-C")
        .arg(dir_path)
        .arg("branch")
        .arg("--show-current")
        .output()
        .ok()?;

    if output.status.success() {
        let branch = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if !branch.is_empty() {
            return Some(branch);
        }
    }

    None
}

pub fn format_size(size: u64) -> String {
    if size < 1000 {
        format!("{}B", size)
    } else if size < 1_000_000 {
        format!("{}KB", size / 1000)
    } else if size < 1_000_000_000 {
        format!("{}MB", size / 1_000_000)
    } else {
        format!("{}GB", size / 1_000_000_000)
    }
}

pub fn format_permissions(mode: u32) -> String {
    format!("{:03o}", mode & 0o777)
}

pub fn format_modified(time: SystemTime) -> String {
    let seconds = time
        .duration_since(SystemTime::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);

    let days = seconds / 86400;
    let sec_in_day = seconds % 86400;
    let hour = sec_in_day / 3600;
    let min = (sec_in_day % 3600) / 60;

    let z = (days as i64) + 719468;
    let era = (if z >= 0 { z } else { z - 146096 }) / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = (mp as i64) + (if mp < 10 { 3 } else { -9 });
    let year = y + (if m <= 2 { 1 } else { 0 });

    format!("{:04}-{:02}-{:02} {:02}:{:02}", year, m, d, hour, min)
}

pub fn unpack_archive(archive_path: &Path, target_dir: &Path) -> Result<(), String> {
    let script = r#"
import sys, os, shutil, gzip

archive = sys.argv[1]
target_dir = sys.argv[2]

base_name = os.path.basename(archive)
if base_name.endswith('.tar.gz') or base_name.endswith('.tgz') or base_name.endswith('.tar.xz') or base_name.endswith('.tar.zst') or base_name.endswith('.tar.bz2') or base_name.endswith('.tar'):
    shutil.unpack_archive(archive, target_dir)
elif base_name.endswith('.zip'):
    shutil.unpack_archive(archive, target_dir)
elif base_name.endswith('.gz'):
    out_name = base_name[:-3]
    out_path = os.path.join(target_dir, out_name)
    with gzip.open(archive, 'rb') as f_in:
        with open(out_path, 'wb') as f_out:
            f_out.write(f_in.read())
else:
    try:
        shutil.unpack_archive(archive, target_dir)
    except Exception as e:
        sys.exit(1)
"#;

    let status = Command::new("python3")
        .arg("-c")
        .arg(script)
        .arg(archive_path)
        .arg(target_dir)
        .status();

    match status {
        Ok(s) if s.success() => Ok(()),
        _ => Err("Failed to unpack archive".to_string()),
    }
}
MY_END_OF_FILE"}

