            app.input_buffer.clear();
        }
        Key::Char('c') => {
            if let Some(name) = app.get_selected_item().map(|i| i.name.clone()) {
                app.mode = AppMode::Rename;
                app.input_buffer = name;
            }
        }
        Key::Char('d') => {
            app.delete_item('0', false);
        }
        Key::Char('y') => {
            app.yank_item('0', false);
        }
        Key::Char('p') => {
            app.put_item('0');
