use std::io::{self, Read, Write};
use std::os::unix::io::AsRawFd;
use std::process::Command;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Key {
    Char(char),
    Ctrl(char),
    Alt(char),
    Up,
    Down,
    Left,
    Right,
    AltUp,
    AltDown,
    Enter,
    Backspace,
    Esc,
    Unknown,
}

pub struct Terminal {
    raw_mode: bool,
}

impl Terminal {
    pub fn new() -> Self {
        Terminal { raw_mode: false }
    }

    pub fn enable_raw_mode(&mut self) {
        if !self.raw_mode {
            let _ = Command::new("stty").args(["raw", "-echo"]).status();
            self.raw_mode = true;
            print!("\x1b7\x1b[?25l\x1b[?1049h\x1b[2J");
            let _ = io::stdout().flush();
        }
    }

    pub fn disable_raw_mode(&mut self) {
        if self.raw_mode {
            print!("\x1b[?25h\x1b[?1049l\x1b8");
            let _ = io::stdout().flush();
            let _ = Command::new("stty").args(["-raw", "echo"]).status();
            self.raw_mode = false;
        }
    }

    pub fn get_size() -> Option<(u16, u16)> {
        let output = Command::new("stty").arg("size").output().ok()?;
        if !output.status.success() {
            return None;
        }
        let s = String::from_utf8_lossy(&output.stdout);
        let mut parts = s.split_whitespace();
        let rows: u16 = parts.next()?.parse().ok()?;
        let cols: u16 = parts.next()?.parse().ok()?;
        Some((cols, rows))
    }

    pub fn read_key(&self) -> Option<Key> {
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        let mut buf = [0u8; 1];

        if handle.read(&mut buf).ok()? == 0 {
            return None;
        }

        let b = buf[0];
        match b {
            0x08 | 0x7f => Some(Key::Backspace),
            0x0d | 0x0a => Some(Key::Enter),
            0x00..=0x07 | 0x09 | 0x0b..=0x0c | 0x0e..=0x1a | 0x1c..=0x1f => {
                let c = (b + 0x60) as char;
                Some(Key::Ctrl(c))
            }
            0x1b => {
                let mut seq = [0u8; 5];
                if let Ok(n) = read_nonblocking(&mut handle, &mut seq) {
                    if n == 0 {
                        return Some(Key::Esc);
                    }
                    if seq[0] == b'[' {
                        match seq[1] {
                            b'A' => Some(Key::Up),
                            b'B' => Some(Key::Down),
                            b'C' => Some(Key::Right),
                            b'D' => Some(Key::Left),
                            b'1' => {
                                if n >= 4 && seq[2] == b';' && seq[3] == b'3' {
                                    match seq[4] {
                                        b'A' => Some(Key::AltUp),
                                        b'B' => Some(Key::AltDown),
                                        _ => Some(Key::Unknown),
                                    }
                                } else {
                                    Some(Key::Unknown)
                                }
                            }
                            _ => Some(Key::Unknown),
                        }
                    } else {
                        let c = seq[0] as char;
                        Some(Key::Alt(c))
                    }
                } else {
                    Some(Key::Esc)
                }
            }
            0x20..=0x7e => Some(Key::Char(b as char)),
            _ => Some(Key::Unknown),
        }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        self.disable_raw_mode();
    }
}

fn read_nonblocking<R: Read>(reader: &mut R, buf: &mut [u8]) -> io::Result<usize> {
    use libc::{poll, pollfd, POLLIN};
    let mut fds = pollfd {
        fd: io::stdin().as_raw_fd(),
        events: POLLIN,
        revents: 0,
    };
