{"command":"cat << 'MY_END_OF_FILE' > src/app.rs
use crate::cli::CliArgs;
use crate::config::Config;
use crate::fs::{self, FileItem};
use std::collections::HashMap;
use std::env;
use std::fs::{self as std_fs, File, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AppMode {
    Normal,
    Search,
    Command,
    NewFile,
    NewDir,
    Rename,
    Visual,
    ConfirmTrash,
    RegisterView,
    HelpView,
}

#[derive(Debug, Clone)]
pub enum UndoAction {
    Delete {
        original_paths: Vec<PathBuf>,
        trash_paths: Vec<PathBuf>,
    },
    Put {
        created_paths: Vec<PathBuf>,
    },
    Rename {
        old_path: PathBuf,
        new_path: PathBuf,
    },
}

pub struct App {
    pub current_dir: PathBuf,
    pub items: Vec<FileItem>,
    pub cursor_idx: usize,
    pub scroll_offset: usize,
    pub history: Vec<PathBuf>,
    pub history_idx: usize,

    pub show_hidden: bool,
    pub sort_by_time: bool,
    pub preview_enabled: bool,
    pub preview_split_vertical: bool,
    pub preview_scroll: usize,

    pub mode: AppMode,
    pub input_buffer: String,
    pub registers: HashMap<char, Vec<PathBuf>>,

    pub visual_anchor: Option<usize>,
    pub visual_selected: Vec<usize>,

    pub search_matches: Vec<usize>,
    pub search_match_pointer: usize,

    pub message: Option<String>,
    pub config: Config,
    pub undo_stack: Vec<UndoAction>,
    pub redo_stack: Vec<UndoAction>,

    pub logging_enabled: bool,
    pub log_file: Option<File>,
    pub exit_requested: bool,
}

impl App {
    pub fn new(args: CliArgs) -> Self {
        let config = Config::load();
        let current_dir = args.target_path.clone();

        let mut log_file = None;
        if args.logging_enabled {
            log_file = init_log_file();
            if let Some(ref mut f) = log_file {
                let now = fs::format_modified(SystemTime::now());
                let time_str = &now[11..];
                let _ = writeln!(f, "{}:00 [INFO] ===START===", time_str);
            }
        }

        let show_hidden = config.default_show_hidden;

        let mut app = App {
            current_dir: current_dir.clone(),
            items: Vec::new(),
            cursor_idx: 0,
            scroll_offset: 0,
            history: vec![current_dir.clone()],
            history_idx: 0,

            show_hidden,
            sort_by_time: false,
            preview_enabled: false,
            preview_split_vertical: true,
            preview_scroll: 0,

            mode: AppMode::Normal,
            input_buffer: String::new(),
            registers: HashMap::new(),

            visual_anchor: None,
            visual_selected: Vec::new(),

            search_matches: Vec::new(),
            search_match_pointer: 0,

            message: None,
            config,
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),

            logging_enabled: args.logging_enabled,
            log_file,
            exit_requested: false,
        };

        app.refresh_items();
        app
    }

    pub fn log_error(&mut self, msg: &str) {
        if let Some(ref mut f) = self.log_file {
            let now = fs::format_modified(SystemTime::now());
            let time_str = &now[11..];
            let _ = writeln!(f, "{}:00 [ERROR] {}", time_str, msg);
        }
    }

    pub fn refresh_items(&mut self) {
        self.items = fs::list_directory(&self.current_dir, self.show_hidden, self.sort_by_time);
        if self.items.is_empty() {
            self.cursor_idx = 0;
            self.scroll_offset = 0;
        } else if self.cursor_idx >= self.items.len() {
            self.cursor_idx = self.items.len() - 1;
        }
    }

    pub fn set_current_dir(&mut self, new_dir: PathBuf) {
        if new_dir.exists() && new_dir.is_dir() {
            self.current_dir = new_dir;
            if self.history_idx + 1 < self.history.len() {
                self.history.truncate(self.history_idx + 1);
            }
            self.history.push(self.current_dir.clone());
            self.history_idx = self.history.len() - 1;
            self.cursor_idx = 0;
            self.scroll_offset = 0;
            self.preview_scroll = 0;
            self.refresh_items();
        }
    }

    pub fn get_selected_item(&self) -> Option<&FileItem> {
        self.items.get(self.cursor_idx)
    }

    pub fn delete_item(&mut self, reg: char, append: bool) {
        let targets = if self.mode == AppMode::Visual {
            self.get_visual_selected_paths()
        } else if let Some(item) = self.get_selected_item() {
            vec![item.path.clone()]
        } else {
            Vec::new()
        };

        if targets.is_empty() {
            return;
        }

        let trash_dir = get_trash_dir();
        let _ = std_fs::create_dir_all(&trash_dir);

        let timestamp = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);

        let mut trash_paths = Vec::new();
        let mut yanked_paths = Vec::new();

        for target in &targets {
            let filename = target.file_name().unwrap_or_default().to_string_lossy();
            let trash_name = format!("{}_{}", timestamp, filename);
            let trash_path = trash_dir.join(trash_name);

            if std_fs::rename(target, &trash_path).is_ok() {
                trash_paths.push(trash_path.clone());
                yanked_paths.push(target.clone());
            }
        }

        let count = yanked_paths.len();
        if count > 0 {
            if append {
                self.registers.entry(reg).or_insert_with(Vec::new).extend(yanked_paths);
            } else {
                self.registers.insert(reg, yanked_paths.clone());
            }

            self.undo_stack.push(UndoAction::Delete {
                original_paths: targets,
                trash_paths,
            });

            if count == 1 {
                self.message = Some("1 item yanked.".to_string());
            } else {
                self.message = Some(format!("{} items yanked.", count));
            }
        }

        self.mode = AppMode::Normal;
        self.refresh_items();
    }

    pub fn yank_item(&mut self, reg: char, append: bool) {
        let targets = if self.mode == AppMode::Visual {
            self.get_visual_selected_paths()
        } else if let Some(item) = self.get_selected_item() {
            vec![item.path.clone()]
        } else {
            Vec::new()
        };

        let count = targets.len();
        if count > 0 {
            if append {
                self.registers.entry(reg).or_insert_with(Vec::new).extend(targets);
            } else {
                self.registers.insert(reg, targets);
            }

            if count == 1 {
                self.message = Some("1 item yanked.".to_string());
            } else {
                self.message = Some(format!("{} items yanked.", count));
            }
        }

        self.mode = AppMode::Normal;
    }

    pub fn put_item(&mut self, reg: char) {
        let paths = match self.registers.get(&reg) {
            Some(p) if !p.is_empty() => p.clone(),
            _ => return,
        };

        let mut created_paths = Vec::new();
        let start_time = std::time::Instant::now();

        for src in &paths {
            if !src.exists() {
                continue;
            }
            let filename = src.file_name().unwrap_or_default().to_string_lossy().to_string();
            let dest = get_non_conflicting_path(&self.current_dir, &filename);

            if src.is_dir() {
                if copy_dir_all(src, &dest).is_ok() {
                    created_paths.push(dest);
                }
            } else {
                if std_fs::copy(src, &dest).is_ok() {
                    created_paths.push(dest);
                }
            }
        }

        let elapsed = start_time.elapsed().as_secs_f64();
        let count = created_paths.len();

        if count > 0 {
            self.undo_stack.push(UndoAction::Put {
                created_paths,
            });
            if count == 1 {
                self.message = Some(format!("1 item inserted. [{:.2}s]", elapsed));
            } else {
                self.message = Some(format!("{} items inserted. [{:.2}s]", count, elapsed));
            }
        }

        self.refresh_items();
    }

    pub fn undo(&mut self) {
        if let Some(action) = self.undo_stack.pop() {
            match &action {
                UndoAction::Delete { original_paths, trash_paths } => {
                    for (orig, trash) in original_paths.iter().zip(trash_paths.iter()) {
                        let _ = std_fs::rename(trash, orig);
                    }
                }
                UndoAction::Put { created_paths } => {
                    for p in created_paths {
                        if p.is_dir() {
                            let _ = std_fs::remove_dir_all(p);
                        } else {
                            let _ = std_fs::remove_file(p);
                        }
                    }
                }
                UndoAction::Rename { old_path, new_path } => {
                    let _ = std_fs::rename(new_path, old_path);
                }
            }
            self.redo_stack.push(action);
            self.refresh_items();
        }
    }

    pub fn redo(&mut self) {
        if let Some(action) = self.redo_stack.pop() {
            match &action {
                UndoAction::Delete { original_paths, trash_paths } => {
                    for (orig, trash) in original_paths.iter().zip(trash_paths.iter()) {
                        let _ = std_fs::rename(orig, trash);
                    }
                }
                UndoAction::Put { created_paths: _ } => {
                }
                UndoAction::Rename { old_path, new_path } => {
                    let _ = std_fs::rename(old_path, new_path);
                }
            }
            self.undo_stack.push(action);
            self.refresh_items();
        }
    }

    pub fn get_visual_selected_paths(&self) -> Vec<PathBuf> {
        if let Some(anchor) = self.visual_anchor {
            let start = anchor.min(self.cursor_idx);
            let end = anchor.max(self.cursor_idx);
            let mut res = Vec::new();
            for i in start..=end {
                if let Some(item) = self.items.get(i) {
                    res.push(item.path.clone());
                }
            }
            res
        } else {
            Vec::new()
        }
    }

    pub fn exit_app(&mut self, save_lwd: bool) {
        if self.logging_enabled {
            if let Some(ref mut f) = self.log_file {
                let now = fs::format_modified(SystemTime::now());
                let time_str = &now[11..];
                let _ = writeln!(f, "{}:00 [INFO] ===FINISH===", time_str);
            }
        }

        if save_lwd {
            if let Ok(pid_str) = env::var("SHELL_PID") {
                let runtime_dir = env::var("XDG_RUNTIME_DIR")
                    .map(|r| PathBuf::from(r).join("felix"))
                    .or_else(|_| env::var("TMPDIR").map(|t| PathBuf::from(t).join("felix")))
                    .unwrap_or_else(|_| PathBuf::from("/tmp/felix"));

                let _ = std_fs::create_dir_all(&runtime_dir);
                let lwd_file = runtime_dir.join(pid_str);
                let _ = std_fs::write(lwd_file, self.current_dir.to_string_lossy().as_bytes());
            }
        }

        self.exit_requested = true;
    }
}

fn init_log_file() -> Option<File> {
    let xdg_data = env::var("XDG_DATA_HOME").ok();
    let home = env::var("HOME").ok();

    let log_dir = if let Some(xdg) = xdg_data {
        PathBuf::from(xdg).join("felix").join("log")
    } else if let Some(h) = home {
        PathBuf::from(h).join(".local").join("share").join("felix").join("log")
    } else {
        PathBuf::from("/tmp/felix/log")
    };

    let _ = std_fs::create_dir_all(&log_dir);

    let now = fs::format_modified(SystemTime::now());
    let filename = format!("{}-{}-00.log", &now[..10], &now[11..16].replace(':', "-"));
    let log_path = log_dir.join(filename);

    OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path)
        .ok()
}

pub fn get_trash_dir() -> PathBuf {
    if let Ok(xdg) = env::var("XDG_DATA_HOME") {
        PathBuf::from(xdg).join("felix").join("Trash")
    } else if let Ok(home) = env::var("HOME") {
        PathBuf::from(home).join(".local").join("share").join("felix").join("Trash")
    } else {
        PathBuf::from("/tmp/felix/Trash")
    }
}

fn get_non_conflicting_path(dir: &Path, filename: &str) -> PathBuf {
    let mut candidate = dir.join(filename);
    if !candidate.exists() {
        return candidate;
    }

    let path = Path::new(filename);
    let stem = path.file_stem().unwrap_or_default().to_string_lossy();
    let ext = path.extension().map(|e| e.to_string_lossy());

    let mut count = 1;
    loop {
        let new_name = match &ext {
            Some(e) => format!("{}_{}.{}", stem, count, e),
            None => format!("{}_{}", stem, count),
        };
        candidate = dir.join(new_name);
        if !candidate.exists() {
            return candidate;
        }
        count += 1;
    }
}

fn copy_dir_all(src: &Path, dst: &Path) -> std::io::Result<()> {
    std_fs::create_dir_all(dst)?;
    for entry in std_fs::read_dir(src)? {
        let entry = entry?;
        let ty = entry.file_type()?;
        if ty.is_dir() {
            copy_dir_all(&entry.path(), &dst.join(entry.file_name()))?;
        } else {
            std_fs::copy(entry.path(), dst.join(entry.file_name()))?;
        }
    }
    Ok(())
}
MY_END_OF_FILE"}

